import type {ReactNode} from 'react';
import React, {useCallback, useMemo, useState} from 'react';

import {Button, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import type {
    TrackerSelectGroup,
    TrackerSelectItem,
    TrackerSelectItemValueBase,
    TrackerSelectProps,
} from '../TrackerSelect';
import {TrackerSelect} from '../TrackerSelect';

import {cnFieldsSelect} from './FieldsSelect.classname';
import {FieldsActions} from './components/FieldsActions/FieldsActions';
import {useSearch} from './hooks/useSearch';
import {defaultMessages} from './i18n';
import {filterGroups} from './utils/filterGroups';
import {getGroupId} from './utils/getGroupId';
import {getGroupName} from './utils/getGroupName';
import {splitGroupsByTags} from './utils/splitGroupsByTags';

import './FieldsSelect.scss';

export type FieldsSelectProps<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = {
    className?: string;
    groups?: TrackerSelectGroup<Value>[];
    selectedItems?: TrackerSelectItem<Value>[];
    loading?: boolean;
    onItemSelect?: (item: TrackerSelectItem<TrackerSelectItemValueBase>) => void;
    onItemDeselect?: (item: TrackerSelectItem<TrackerSelectItemValueBase>) => void;
    onOpenChange?: (open: boolean) => void;
    onSubmit?: () => void | Promise<void>;
    onReset?: () => void;
    onSearchChange?: (search: string) => void;
    open?: boolean;
    showSearch?: boolean;
    showSubmit?: boolean;
    showReset?: boolean;
    splitDataByTag?: boolean;
    withGroupTags?: boolean;
    footer?: ReactNode;
    expandGroupsOnSearch?: boolean;
    expandSystemGroup?: boolean;
} & Omit<TrackerSelectProps<Value>, 'onOpenChange' | 'open'>;

export const FieldsSelect = <Value extends TrackerSelectItemValueBase>({
    className,
    groups,
    selectedItems,
    loading = false,
    onItemSelect,
    onItemDeselect,
    onOpenChange,
    onSubmit,
    onReset,
    onSearchChange,
    showSearch = true,
    showSubmit = true,
    showReset = false,
    splitDataByTag = false,
    withGroupTags = false,
    expandGroupsOnSearch,
    expandSystemGroup,
    open,
    ...trackerSelectProps
}: FieldsSelectProps<Value>) => {
    const [activeTag, setActiveTag] = useState('all');
    const [submitLoading, setSubmitLoading] = useState(false);

    const {search, handleSearch} = useSearch({onSearchChange});

    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);

    const isGroupExpandedByDefault = useCallback(
        (group: TrackerSelectGroup<TrackerSelectItemValueBase>) => {
            if (search) {
                return expandGroupsOnSearch || false;
            }

            if (expandSystemGroup) {
                return Number(group.id) === 1;
            }

            return false;
        },
        [expandGroupsOnSearch, expandSystemGroup, search],
    );

    // --- Group assembly ---

    const filteredGroups = useMemo(() => filterGroups(groups, search), [groups, search]);

    const allGroups = useMemo<TrackerSelectGroup<TrackerSelectItemValueBase>[]>(() => {
        const base = filteredGroups ?? [];

        const afterSplit = splitDataByTag ? splitGroupsByTags(base) : base;

        if (withGroupTags) {
            return afterSplit
                .filter((group) => group.type !== 'named')
                .map((group) => ({
                    ...group,
                    id: getGroupId(group),
                    name: getGroupName(group),
                }));
        }

        return afterSplit;
    }, [filteredGroups, splitDataByTag, withGroupTags]);

    // --- Active-tag filtering ---

    const visibleGroups = useMemo<TrackerSelectGroup<TrackerSelectItemValueBase>[]>(() => {
        if (activeTag === 'selected') {
            // Show only groups that contain at least one selected item
            const selectedIds = new Set(selectedItems?.map((s) => s.id) ?? []);

            return allGroups
                .map((group) => {
                    const filteredItems = Object.entries(group.items ?? {}).reduce(
                        (res, [key, item]) => {
                            if (selectedIds.has(item.id)) {
                                return {...res, [key]: item};
                            }
                            return res;
                        },
                        {},
                    );

                    return {...group, items: filteredItems};
                })
                .filter((group) => Object.keys(group.items ?? {}).length > 0);
        }

        if (activeTag !== 'all') {
            const tagGroup = allGroups.find((group) => group.id === activeTag);

            return tagGroup ? [tagGroup] : allGroups;
        }

        return allGroups;
    }, [activeTag, allGroups, selectedItems]);

    // --- Item click handler ---

    const handleItemClick = useCallback(
        (item: TrackerSelectItem<TrackerSelectItemValueBase>) => {
            const isSelected = selectedItems?.some((s) => s.id === item.id);

            if (isSelected) {
                onItemDeselect?.(item);
            } else {
                onItemSelect?.(item);
            }
        },
        [selectedItems, onItemSelect, onItemDeselect],
    );

    // --- Submit handler (supports async) ---

    const handleSubmit = useCallback(async () => {
        try {
            setSubmitLoading(true);
            await onSubmit?.();
            onOpenChange?.(false);
        } catch (error) {
            console.error(error);
        } finally {
            setSubmitLoading(false);
        }
    }, [onSubmit, onOpenChange]);

    const handleReset = useCallback(() => {
        onReset?.();
    }, [onReset]);

    const handleOpenChange = useCallback(
        (nextOpen: boolean) => {
            onOpenChange?.(nextOpen);
        },
        [onOpenChange],
    );

    // --- Tag switcher subHeader ---

    const subHeader = useMemo(() => {
        const hasSelectedItems = Boolean(selectedItems?.length);

        // Collect 'data'-type groups for per-group tag buttons
        const dataGroups = allGroups.filter((group) => group.type === 'data');

        const hasTags = hasSelectedItems || dataGroups.length > 0;

        if (!hasTags) {
            return undefined;
        }

        return (
            <div className={cnFieldsSelect('tag-list')}>
                <Button
                    onClick={() => setActiveTag('all')}
                    selected={activeTag === 'all'}
                    className={cnFieldsSelect('tag')}
                >
                    {t('all')}
                </Button>

                {hasSelectedItems && (
                    <Button
                        onClick={() => setActiveTag('selected')}
                        selected={activeTag === 'selected'}
                        className={cnFieldsSelect('tag')}
                    >
                        {t('selected')}
                    </Button>
                )}

                {dataGroups.map((group) => (
                    <Button
                        key={group.id}
                        onClick={() => setActiveTag(group.id)}
                        selected={activeTag === group.id}
                        className={cnFieldsSelect('tag')}
                    >
                        {group.name}
                    </Button>
                ))}
            </div>
        );
    }, [selectedItems, allGroups, activeTag, t]);

    return (
        <TrackerSelect
            className={cnFieldsSelect(null, className)}
            onOpenChange={handleOpenChange}
            groups={visibleGroups}
            selectedItems={selectedItems}
            isLoading={loading}
            onItemClick={handleItemClick}
            onSubmit={submitLoading ? undefined : handleSubmit}
            onReset={handleReset}
            onSearchChange={handleSearch}
            showSearch={showSearch}
            showSubmit={showSubmit}
            showReset={showReset}
            subHeader={withGroupTags ? subHeader : undefined}
            showSelectedGroup={!search || activeTag === 'selected'}
            isGroupExpandedByDefault={isGroupExpandedByDefault}
            itemActions={FieldsActions}
            open={open ?? false}
            submitDisabled={submitLoading}
            {...trackerSelectProps}
        />
    );
};

FieldsSelect.displayName = 'FieldsSelect';
